/**
 * Katalog für den Badplaner (/badplaner).
 *
 * Platten bzw. Looks, Akzentflächen, Möbel (Unterbau und Waschtischplatte),
 * Armaturen und Keramikfarben je Badpaket. Jede Option hat einen englischen
 * `prompt`-Text, den die API (api/badplaner.ts) in die Anweisung an das
 * Bildmodell einsetzt. `image` ist der Pfad des Musterbildes unter public/,
 * `src` die Quelle beim Lieferanten (scripts/fetch-swatches.mjs lädt fehlende
 * Muster beim Build herunter). Muster ohne `src` liegen fest im Repo
 * (Edonè aus dem Katalog-PDF, Treemme-Fotos).
 *
 * Keine Option ohne Bild: Farben, für die der Lieferant kein Muster
 * veröffentlicht, stehen nicht in diesem Katalog.
 *
 * NICHT VON HAND ÄNDERN: erzeugt von scratchpad/gen_badplaner_data.py aus den
 * Materialarchiven. Änderungen gehören in das Skript.
 *
 * Die Datei wird sowohl von der Seite als auch von der Serverless-Funktion
 * importiert: hier deshalb nur Konstanten und reine Funktionen, keine
 * Browser-APIs.
 */

export type PackageId = 'essenza' | 'colore' | 'atelier';
export type RoomType = 'badezimmer' | 'gaeste-wc';

/** Fläche, auf der ein zweites Material als Akzent liegt (nur Atelier). */
export type AccentPlacementId = 'waschtischwand' | 'duschnische';

export interface TileOption {
  id: string;
  label: string;
  supplier: string;
  series: string;
  color: string;
  format: string;        // Standardformat, z. B. "60x120" (cm)
  formats: string[];     // im Paket wählbare Formate
  look?: string;         // nur Atelier: Id des Looks (siehe `looks`)
  note?: string;         // Hinweis unter der Serie
  packages: PackageId[];
  image: string;         // Pfad unter public/
  src?: string | null;   // Originalbild beim Lieferanten
  url: string;           // Produktseite
  prompt: string;        // englische Beschreibung für das Bildmodell
}

/** Atelier: sechs Stimmungen statt Katalog. Nach der Wahl folgen die Materialien. */
export interface LookOption {
  id: string;
  label: string;
  description: string;
  packages: PackageId[];
  image: string;
  src?: string | null;
  prompt: string;
}

/** Zweites Material für genau eine Fläche (Atelier, Variante "Kombination"). */
export interface AccentOption {
  id: string;
  label: string;
  supplier: string;
  collection: string;
  wetOk: boolean;                    // vom Hersteller für Nassbereiche freigegeben
  placement: AccentPlacementId[];    // Flächen, auf denen das Material zulässig ist
  note?: string;
  packages: PackageId[];
  image: string;
  src?: string | null;
  url: string;
  prompt: string;
}

/** Waschtischplatte. */
export interface TopOption {
  id: string;
  label: string;
  supplier: string;
  material: string;
  color: string;
  packages: PackageId[];
  image: string;
  src?: string | null;
  url: string;
  prompt: string;
}

/** Unterbau (Möbelkorpus und Front). */
export interface BaseOption {
  id: string;
  label: string;
  supplier: string;
  collection: string;
  family?: string;
  hex?: string;          // Ersatzfarbe, falls das Muster (noch) nicht geladen ist
  packages: PackageId[];
  image: string;
  src?: string | null;
  url: string;
  prompt: string;
}

/** Waschbeckenart: Aufsatz-, Einbau- oder integriertes Becken. */
export interface BasinTypeOption {
  id: string;
  label: string;
  supplier: string;
  example: string;       // Modell auf dem Foto
  packages?: PackageId[]; // fehlt = in allen Paketen
  image: string;
  src?: string | null;
  url: string;
  prompt: string;
}

/** Armaturenserie mit Foto (Colore zur Wahl, Atelier nur zum Ansehen). */
export interface TapSeriesOption {
  id: string;
  label: string;
  supplier: string;
  shape: string;
  note: string;
  packages: PackageId[];
  image: string;
  src?: string | null;
  url: string;
  prompt: string;
}

export interface ColorOption {
  id: string;
  label: string;
  supplier: string;
  hex: string;
  image?: string | null;
  src?: string | null;
  prompt: string;
  packages: PackageId[];
}

export interface FinishOption {
  id: string;
  label: string;
  supplier: string;
  image?: string | null;
  src?: string | null;
  prompt: string;
  packages: PackageId[];
}

export interface ChoiceOption {
  id: string;
  label: string;
  prompt: string;
  packages?: PackageId[]; // fehlt = in allen Paketen
}

/* ---------- Wählbare Plattenformate je Paket ---------- */

