/* ---------- Hilfen ---------- */

/** Nur die Optionen, die für das gewählte Paket gelten (ohne `packages` = überall). */
const forPackage = <T extends { packages?: PackageId[] }>(list: T[], pkg: PackageId): T[] =>
  list.filter((o) => !o.packages || o.packages.includes(pkg));

/** Alle Auswahllisten für ein Paket, in der Reihenfolge der Schritte auf der Seite. */
export function optionsForPackage(pkg: PackageId) {
  return {
    formats: tileFormats[pkg],
    looks: forPackage(looks, pkg),
    tiles: forPackage(tiles, pkg),
    accentModes: forPackage(accentModes, pkg),
    accentPlacements: forPackage(accentPlacements, pkg),
    accents: forPackage(accents, pkg),
    furniture: forPackage(bases, pkg),   // Unterbau (Name wegen der bestehenden API)
    bases: forPackage(bases, pkg),
    tops: forPackage(tops, pkg),
    basinTypes: forPackage(basinTypes, pkg),
    tapSeriesOptions: forPackage(tapSeriesOptions, pkg),
    finishes: forPackage(tapFinishes, pkg),
    sanitary: forPackage(sanitaryColors, pkg),
    walls: forPackage(wallOptions, pkg),
    showers: forPackage(showerOptions, pkg),
    bathtubs: forPackage(bathtubOptions, pkg),
    basins: forPackage(basinOptions, pkg),
    mirrors: forPackage(mirrorOptions, pkg),
    tapSeries: tapSeries[pkg],
  };
}

/** Platten eines Looks (Atelier). */
export function tilesForLook(lookId: string): TileOption[] {
  return tiles.filter((t) => t.look === lookId);
}

/** Akzentmaterialien, die auf der gewählten Fläche zulässig sind. */
export function accentsForPlacement(placement: AccentPlacementId): AccentOption[] {
  return accents.filter((a) => a.placement.includes(placement));
}

/**
 * Flache Liste aller Musterbilder, die beim Lieferanten liegen (Datei unter
 * public/badplaner/swatches/ und Quelle). Dieselben Daten liegen als
 * scripts/swatches.json, damit scripts/fetch-swatches.mjs sie ohne TypeScript
 * lesen kann. Muster ohne `src` (Edonè, Treemme) liegen fest im Repo.
 */
export const swatchSources: { file: string; src: string }[] = (() => {
  const all: { image?: string | null; src?: string | null }[] = [
    ...looks, ...tiles, ...accents, ...bases, ...tops, ...basinTypes,
    ...tapSeriesOptions, ...sanitaryColors, ...tapFinishes,
  ];
  const seen = new Set<string>();
  const out: { file: string; src: string }[] = [];
  for (const o of all) {
    if (!o.image || !o.src) continue;
    const file = o.image.replace('/badplaner/swatches/', '');
    if (seen.has(file)) continue;
    seen.add(file);
    out.push({ file, src: o.src });
  }
  return out;
})();

